use std::path::PathBuf;
use std::process::{Command, ExitCode};

fn main() -> ExitCode {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let bridge = root.join("bridge").join("transform-host.js");
    let node = env::var_os("JSCODE_SHIFT_NODE").unwrap_or_else(|| "node".into());

    let status = match Command::new(node)
        .arg(bridge)
        .args(env::args_os().skip(1))
        .current_dir(&root)
        .status()
    {
        Ok(status) => status,
        Err(error) => {
            eprintln!("jscodeshift: unable to start Node.js: {error}");
            return ExitCode::from(1);
        }
    };

    match status.code() {
        Some(code) if (0..= u8::MAX as i32).contains(&code) => ExitCode::from(code as u8),
        Some(_) => ExitCode::from(1),
        None => ExitCode::from(1),
    }
}
